UTILITIES_RUNTIME = 'from __future__ import annotations\n\nfrom datetime import datetime, timezone\nfrom hashlib import sha256\nfrom pathlib import Path\nfrom threading import Lock\nfrom typing import Iterable\nimport re\n\nimport cv2\nimport numpy as np\n\nfrom app.services.vision_app.models import (\n    NormalizedRect,\n    UtilityBatchRequest,\n    UtilityGatherAugmentation,\n    UtilityGatherPlan,\n    UtilityGatherRoi,\n)\n\n\n_IMAGE_SUFFIXES = {\'.jpg\', \'.jpeg\', \'.png\', \'.bmp\', \'.tif\', \'.tiff\', \'.webp\'}\n_SAFE_STEM = re.compile(r\'[^A-Za-z0-9_.-]+\')\n\n\nclass UtilityGatherRuntime:\n    """Filesystem-oriented image/ROI harvesting for Vision App Utilities.\n\n    v0.15.1 keeps gathering AI-agnostic while adding deterministic ROI sampling\n    augmentation. The same plan is used by manual capture, offline batch and\n    Workspace-active collection.\n    """\n\n    FULL_OUTPUT_ID = \'__full__\'\n\n    def __init__(self) -> None:\n        self._counter = 0\n        self._lock = Lock()\n\n    @staticmethod\n    def _folder(path: str) -> Path:\n        value = str(path or \'\').strip()\n        if not value:\n            raise ValueError(\'Folder path is empty\')\n        return Path(value).expanduser()\n\n    @classmethod\n    def _images(cls, source_dir: str) -> list[Path]:\n        root = cls._folder(source_dir)\n        if not root.exists():\n            raise FileNotFoundError(f\'Image source folder not found: {root}\')\n        if not root.is_dir():\n            raise NotADirectoryError(f\'Image source is not a folder: {root}\')\n        return sorted(\n            (item for item in root.iterdir() if item.is_file() and item.suffix.lower() in _IMAGE_SUFFIXES),\n            key=lambda item: item.name.lower(),\n        )\n\n    def folder_info(self, source_dir: str) -> dict:\n        images = self._images(source_dir)\n        return {\n            \'source_dir\': str(self._folder(source_dir)),\n            \'count\': len(images),\n            \'first_name\': images[0].name if images else \'\',\n            \'last_name\': images[-1].name if images else \'\',\n        }\n\n    def folder_image(self, source_dir: str, index: int) -> tuple[np.ndarray, Path, int, int]:\n        images = self._images(source_dir)\n        if not images:\n            raise FileNotFoundError(f\'No supported images in source folder: {source_dir}\')\n        resolved = max(0, min(int(index), len(images) - 1))\n        path = images[resolved]\n        image = cv2.imread(str(path), cv2.IMREAD_COLOR)\n        if image is None:\n            raise ValueError(f\'Could not decode image: {path}\')\n        return image, path, resolved, len(images)\n\n    @staticmethod\n    def _safe_stem(value: str) -> str:\n        stem = _SAFE_STEM.sub(\'_\', value.strip()).strip(\'._-\')\n        return (stem or \'sample\')[:120]\n\n    def _capture_stem(self) -> str:\n        with self._lock:\n            self._counter += 1\n            counter = self._counter\n        now = datetime.now(timezone.utc).astimezone()\n        return f"capture_{now.strftime(\'%Y%m%d_%H%M%S_%f\')}_{counter:06d}"\n\n    @staticmethod\n    def _destination(plan: UtilityGatherPlan, destination: str) -> Path:\n        value = str(destination or \'\').strip()\n        if not value:\n            raise ValueError(\'Enabled output has no destination folder\')\n        target = Path(value).expanduser()\n        if target.is_absolute():\n            return target\n        base = str(plan.base_dir or \'\').strip()\n        if not base:\n            raise ValueError(f\'Relative destination requires a base folder: {value}\')\n        return Path(base).expanduser() / target\n\n    @staticmethod\n    def _next_path(folder: Path, stem: str, extension: str) -> Path:\n        candidate = folder / f\'{stem}.{extension}\'\n        if not candidate.exists():\n            return candidate\n        index = 1\n        while True:\n            candidate = folder / f\'{stem}_{index:03d}.{extension}\'\n            if not candidate.exists():\n                return candidate\n            index += 1\n\n    @staticmethod\n    def _encode(image: np.ndarray, plan: UtilityGatherPlan) -> tuple[str, bytes]:\n        extension = \'png\' if plan.image_format == \'png\' else \'jpg\'\n        params: list[int] = []\n        if extension == \'jpg\':\n            params = [int(cv2.IMWRITE_JPEG_QUALITY), int(plan.jpeg_quality)]\n        ok, encoded = cv2.imencode(f\'.{extension}\', image, params)\n        if not ok:\n            raise RuntimeError(f\'Failed to encode gathered image as {extension}\')\n        return extension, encoded.tobytes()\n\n    @staticmethod\n    def _roi_map(rois: Iterable[UtilityGatherRoi]) -> dict[str, UtilityGatherRoi]:\n        result: dict[str, UtilityGatherRoi] = {}\n        for roi in rois:\n            if roi.roi_id in result:\n                raise ValueError(f\'Duplicate gather ROI id: {roi.roi_id}\')\n            result[roi.roi_id] = roi\n        return result\n\n    @staticmethod\n    def _rect_tuple(rect: NormalizedRect) -> tuple[float, float, float, float]:\n        return float(rect.x), float(rect.y), float(rect.w), float(rect.h)\n\n    @staticmethod\n    def _iou(a: tuple[float, float, float, float], b: tuple[float, float, float, float]) -> float:\n        ax, ay, aw, ah = a; bx, by, bw, bh = b\n        x0 = max(ax, bx); y0 = max(ay, by)\n        x1 = min(ax + aw, bx + bw); y1 = min(ay + ah, by + bh)\n        inter = max(0.0, x1 - x0) * max(0.0, y1 - y0)\n        union = aw * ah + bw * bh - inter\n        return 0.0 if union <= 0.0 else inter / union\n\n    @staticmethod\n    def _clamp_rect(cx: float, cy: float, w: float, h: float) -> tuple[float, float, float, float]:\n        w = min(1.0, max(1e-6, w)); h = min(1.0, max(1e-6, h))\n        x = min(max(0.0, cx - w / 2.0), max(0.0, 1.0 - w))\n        y = min(max(0.0, cy - h / 2.0), max(0.0, 1.0 - h))\n        return x, y, w, h\n\n    @staticmethod\n    def _unit_from_hash(seed: str, offset: int) -> float:\n        raw = sha256(seed.encode(\'utf-8\')).digest()\n        start = (offset * 4) % (len(raw) - 4)\n        value = int.from_bytes(raw[start:start + 4], \'big\') / 0xFFFFFFFF\n        return value\n\n    @classmethod\n    def _variant_rects(\n        cls,\n        roi: UtilityGatherRoi,\n        augmentation: UtilityGatherAugmentation,\n        *,\n        seed_stem: str,\n    ) -> list[tuple[str, tuple[float, float, float, float]]]:\n        base = cls._rect_tuple(roi.rect)\n        result: list[tuple[str, tuple[float, float, float, float]]] = []\n        if augmentation.include_original or not augmentation.enabled:\n            result.append((\'orig\', base))\n        if not augmentation.enabled or int(augmentation.extra_variants) <= 0:\n            return result\n\n        min_scale = min(float(augmentation.min_scale), float(augmentation.max_scale))\n        max_scale = max(float(augmentation.min_scale), float(augmentation.max_scale))\n        shift_x = max(0.0, float(augmentation.shift_x_pct))\n        shift_y = max(0.0, float(augmentation.shift_y_pct))\n        bx, by, bw, bh = base\n        center_x = bx + bw / 2.0; center_y = by + bh / 2.0\n        target = int(augmentation.extra_variants)\n        attempts = 0\n        index = 0\n        while len(result) < target + (1 if augmentation.include_original else 0) and attempts < max(64, target * 12):\n            seed = f\'{seed_stem}|{roi.roi_id}|{index}\'\n            dx = (cls._unit_from_hash(seed, 0) * 2.0 - 1.0) * shift_x * bw\n            dy = (cls._unit_from_hash(seed, 1) * 2.0 - 1.0) * shift_y * bh\n            scale = min_scale + cls._unit_from_hash(seed, 2) * (max_scale - min_scale)\n            candidate = cls._clamp_rect(center_x + dx, center_y + dy, bw * scale, bh * scale)\n            attempts += 1; index += 1\n            if cls._iou(base, candidate) + 1e-9 < float(augmentation.min_iou):\n                continue\n            if any(all(abs(a - b) < 1e-6 for a, b in zip(candidate, existing)) for _, existing in result):\n                continue\n            result.append((f\'v{len(result):02d}\', candidate))\n        return result\n\n    @staticmethod\n    def _crop_rect(image: np.ndarray, rect: tuple[float, float, float, float], roi_id: str) -> np.ndarray:\n        height, width = image.shape[:2]\n        x, y, w, h = rect\n        x0 = max(0, min(width - 1, int(round(x * width))))\n        y0 = max(0, min(height - 1, int(round(y * height))))\n        x1 = max(x0 + 1, min(width, int(round((x + w) * width))))\n        y1 = max(y0 + 1, min(height, int(round((y + h) * height))))\n        crop = image[y0:y1, x0:x1]\n        if crop.size == 0:\n            raise ValueError(f\'ROI produced an empty crop: {roi_id}\')\n        return np.ascontiguousarray(crop)\n\n    def save_frame(self, image: np.ndarray, plan: UtilityGatherPlan, *, stem: str | None = None) -> dict:\n        arr = np.asarray(image)\n        if arr.ndim not in {2, 3} or arr.size == 0:\n            raise ValueError(\'Gather source image is empty or invalid\')\n        roi_by_id = self._roi_map(plan.rois)\n        active_routes = [route for route in plan.routes if route.enabled]\n        if not active_routes:\n            raise ValueError(\'At least one gather output must be enabled\')\n\n        seen: set[str] = set()\n        for route in active_routes:\n            if route.output_id in seen:\n                raise ValueError(f\'Duplicate gather route: {route.output_id}\')\n            seen.add(route.output_id)\n            if route.output_id != self.FULL_OUTPUT_ID and route.output_id not in roi_by_id:\n                raise KeyError(f\'Gather route refers to unknown ROI: {route.output_id}\')\n\n        sample_stem = self._safe_stem(stem or self._capture_stem())\n        saved: list[dict] = []\n        failed: list[dict] = []\n        for route in active_routes:\n            variants: list[tuple[str, np.ndarray, tuple[float, float, float, float] | None]]\n            if route.output_id == self.FULL_OUTPUT_ID:\n                variants = [(\'orig\', arr, None)]\n            else:\n                roi = roi_by_id[route.output_id]\n                variants = []\n                for variant_name, rect in self._variant_rects(roi, plan.augmentation, seed_stem=sample_stem):\n                    try:\n                        variants.append((variant_name, self._crop_rect(arr, rect, roi.roi_id), rect))\n                    except Exception as exc:\n                        failed.append({\'output_id\': route.output_id, \'variant\': variant_name, \'error\': str(exc)})\n            for variant_name, payload, rect in variants:\n                try:\n                    folder = self._destination(plan, route.destination)\n                    folder.mkdir(parents=True, exist_ok=True)\n                    extension, encoded = self._encode(payload, plan)\n                    variant_suffix = \'\' if variant_name == \'orig\' else f\'__{variant_name}\'\n                    path = self._next_path(folder, sample_stem + variant_suffix, extension)\n                    temporary = path.with_name(path.name + \'.tmp\')\n                    temporary.write_bytes(encoded)\n                    temporary.replace(path)\n                    item = {\n                        \'output_id\': route.output_id,\n                        \'variant\': variant_name,\n                        \'path\': str(path),\n                        \'width\': int(payload.shape[1]),\n                        \'height\': int(payload.shape[0]),\n                    }\n                    if rect is not None:\n                        item[\'rect\'] = {\'x\': rect[0], \'y\': rect[1], \'w\': rect[2], \'h\': rect[3]}\n                    saved.append(item)\n                except Exception as exc:\n                    failed.append({\'output_id\': route.output_id, \'variant\': variant_name, \'error\': str(exc)})\n\n        return {\n            \'stem\': sample_stem,\n            \'saved_count\': len(saved),\n            \'failed_count\': len(failed),\n            \'saved\': saved,\n            \'failed\': failed,\n        }\n\n    def process_folder(self, request: UtilityBatchRequest) -> dict:\n        images = self._images(request.source_dir)\n        if not images:\n            raise FileNotFoundError(f\'No supported images in source folder: {request.source_dir}\')\n\n        processed = 0\n        saved_count = 0\n        failed_count = 0\n        errors: list[dict] = []\n        for path in images:\n            image = cv2.imread(str(path), cv2.IMREAD_COLOR)\n            if image is None:\n                failed_count += 1\n                errors.append({\'source\': str(path), \'error\': \'decode failed\'})\n                continue\n            try:\n                result = self.save_frame(image, request, stem=f\'{self._safe_stem(path.stem)}__gathered\')\n                processed += 1\n                saved_count += int(result[\'saved_count\'])\n                failed_count += int(result[\'failed_count\'])\n                for item in result[\'failed\']:\n                    if len(errors) < 50:\n                        errors.append({\'source\': str(path), **item})\n            except Exception as exc:\n                failed_count += 1\n                if len(errors) < 50:\n                    errors.append({\'source\': str(path), \'error\': str(exc)})\n\n        return {\n            \'source_dir\': str(self._folder(request.source_dir)),\n            \'source_count\': len(images),\n            \'processed_count\': processed,\n            \'saved_count\': saved_count,\n            \'failed_count\': failed_count,\n            \'errors\': errors,\n        }\n'
UTILITIES_WORKSPACE = 'import { Camera, ChevronLeft, ChevronRight, FolderOpen, Image as ImageIcon, Layers3, Loader2, Pipette, Plus, RefreshCw, Save, Sparkles, Trash2, X } from \'lucide-react\';\nimport { useEffect, useMemo, useState } from \'react\';\nimport { VisionAppAPI, type MasterRoi, type NormalizedRect, type UtilityBatchResult, type UtilityBurstResult, type UtilityGatherAugmentation, type UtilityGatherPlan, type UtilityGatherResult, type WorkspaceDefinition } from \'../../api/visionAppApi\';\nimport { VisionViewport } from \'./VisionViewport\';\n\ntype Props={\n  programId:string;\n  workspace:WorkspaceDefinition;\n  workspaceAlias:string;\n  onWorkspace:(next:WorkspaceDefinition)=>void;\n  onPersistWorkspace:(next:WorkspaceDefinition)=>Promise<void>;\n  onError:(message:string)=>void;\n};\n\ntype SourceMode=\'camera\'|\'folder\';\ntype ActiveMode=\'off\'|\'utilities_only\'|\'both\';\ntype RouteState={enabled:boolean;destination:string};\nconst FULL=\'__full__\';\nconst safeFolder=(value:string)=>value.trim().replace(/[^A-Za-z0-9_.-]+/g,\'_\').replace(/^[_\\.-]+|[_\\.-]+$/g,\'\')||\'roi\';\nconst absolutePath=(value:string)=>/^(?:[A-Za-z]:[\\\\/]|\\\\\\\\|\\/)/.test(value.trim());\nconst manualRoi=(rect:NormalizedRect,index:number):MasterRoi=>({roi_id:`utility_${Date.now()}_${Math.random().toString(36).slice(2,6)}`,name:`Utility ROI ${index+1}`,alias:`UTILITY_${index+1}`,rect,enabled:true});\nconst defaultAug=():UtilityGatherAugmentation=>({enabled:false,include_original:true,extra_variants:0,shift_x_pct:.05,shift_y_pct:.05,min_scale:1,max_scale:1.10,min_iou:.70});\nconst defaultPlan=():UtilityGatherPlan=>({base_dir:\'\',routes:[{output_id:FULL,enabled:true,destination:\'full\'}],rois:[],image_format:\'jpg\',jpeg_quality:94,augmentation:defaultAug()});\n\nexport const UtilitiesWorkspace=({programId,workspace,workspaceAlias,onWorkspace,onPersistWorkspace,onError}:Props)=>{\n const persisted=workspace.utilities?.gathering;\n const seedPlan=persisted?.plan??defaultPlan();\n const masterIds=useMemo(()=>new Set(workspace.master.rois.map(item=>item.roi_id)),[workspace.master.rois]);\n const [mode,setMode]=useState<SourceMode>(\'camera\');\n const [activeMode,setActiveMode]=useState<ActiveMode>(persisted?.mode??\'off\');\n const [samplesPerCycle,setSamplesPerCycle]=useState(persisted?.samples_per_cycle??1);\n const [intervalMs,setIntervalMs]=useState(persisted?.interval_ms??0);\n const [baseDir,setBaseDir]=useState(seedPlan.base_dir??\'\');\n const [sourceDir,setSourceDir]=useState(\'\');const [folderCount,setFolderCount]=useState(0);const [folderIndex,setFolderIndex]=useState(0);const [folderName,setFolderName]=useState(\'\');const [previewUrl,setPreviewUrl]=useState<string|null>(null);\n const [busy,setBusy]=useState(false);const [status,setStatus]=useState(\'Ready\');const [lastResult,setLastResult]=useState<UtilityGatherResult|UtilityBurstResult|UtilityBatchResult|null>(null);\n const [useMaster,setUseMaster]=useState(true);\n const [manual,setManual]=useState<MasterRoi[]>(()=>seedPlan.rois.filter(item=>!masterIds.has(item.roi_id)).map(item=>({roi_id:item.roi_id,name:item.name,alias:safeFolder(item.name).toUpperCase(),rect:item.rect,enabled:true})));\n const [drawMode,setDrawMode]=useState(false);const [selectedId,setSelectedId]=useState<string|null>(null);\n const [routes,setRoutes]=useState<Record<string,RouteState>>(()=>Object.fromEntries(seedPlan.routes.map(item=>[item.output_id,{enabled:item.enabled,destination:item.destination}])));\n const [augmentation,setAugmentation]=useState<UtilityGatherAugmentation>(seedPlan.augmentation??defaultAug());\n const [paintDestination,setPaintDestination]=useState<string|null>(null);\n const [manualBurst,setManualBurst]=useState(Math.max(1,persisted?.samples_per_cycle??10));\n const [manualInterval,setManualInterval]=useState(Math.max(0,persisted?.interval_ms??100));\n const camera=workspace.cameras.devices.find(item=>item.declaration_id===workspace.camera_id)??null;\n const allRois=useMemo(()=>[...(useMaster?workspace.master.rois:[]),...manual],[useMaster,workspace.master.rois,manual]);\n const outputRows=useMemo(()=>[{id:FULL,name:\'Full Frame\',kind:\'frame\'},...allRois.map(roi=>({id:roi.roi_id,name:roi.name,kind:roi.roi_id.startsWith(\'utility_\')?\'manual\':\'master\'}))],[allRois]);\n useEffect(()=>{setRoutes(current=>{const next={...current};for(const row of outputRows){if(!next[row.id])next[row.id]={enabled:true,destination:row.id===FULL?\'full\':safeFolder(row.name)};}for(const id of Object.keys(next)){if(!outputRows.some(row=>row.id===id))delete next[id];}return next;});},[outputRows]);\n useEffect(()=>()=>{if(previewUrl)URL.revokeObjectURL(previewUrl);},[previewUrl]);\n useEffect(()=>{const onKey=(event:KeyboardEvent)=>{if(event.key===\'Escape\')setPaintDestination(null);};window.addEventListener(\'keydown\',onKey);return()=>window.removeEventListener(\'keydown\',onKey);},[]);\n const plan=():UtilityGatherPlan=>({base_dir:baseDir,routes:outputRows.map(row=>({output_id:row.id,enabled:routes[row.id]?.enabled??true,destination:routes[row.id]?.destination??\'\'})),rois:allRois.map(roi=>({roi_id:roi.roi_id,name:roi.name,rect:roi.rect})),image_format:\'jpg\',jpeg_quality:94,augmentation});\n const nextWorkspace=():WorkspaceDefinition=>({...workspace,utilities:{gathering:{mode:activeMode,plan:plan(),samples_per_cycle:Math.max(1,samplesPerCycle),interval_ms:Math.max(0,intervalMs)}}});\n // Keep the parent draft current so the normal Program Save button also persists Utilities.\n useEffect(()=>{const next=nextWorkspace();const a=JSON.stringify(next.utilities);const b=JSON.stringify(workspace.utilities);if(a!==b)onWorkspace(next);},[activeMode,samplesPerCycle,intervalMs,baseDir,routes,manual,useMaster,augmentation]);\n const showBlob=(blob:Blob,name:string)=>{setFolderName(name);setPreviewUrl(old=>{if(old)URL.revokeObjectURL(old);return URL.createObjectURL(blob);});};\n const validate=()=>{const active=outputRows.filter(row=>routes[row.id]?.enabled!==false);if(!active.length)throw new Error(\'Enable at least one output.\');for(const row of active){if(!(routes[row.id]?.destination??\'\').trim())throw new Error(`${row.name} has no destination folder.`);}if(active.some(row=>!absolutePath(routes[row.id]?.destination??\'\'))&&!baseDir.trim())throw new Error(\'Set a base output folder when using relative destinations.\');if(augmentation.enabled&&!augmentation.include_original&&augmentation.extra_variants<1)throw new Error(\'Augmentation needs Include original or at least one extra variant.\');};\n const saveConfig=async()=>{try{validate();setBusy(true);await onPersistWorkspace(nextWorkspace());setStatus(`Utilities config saved · Active ${activeMode}`);}catch(e:any){onError(e?.response?.data?.detail||e?.message||\'Utilities save failed\');}finally{setBusy(false);}};\n const loadFolder=async(index=0)=>{if(!sourceDir.trim())return;try{setBusy(true);const info=await VisionAppAPI.utilityFolderInfo(programId,workspaceAlias,sourceDir.trim());setFolderCount(info.count);if(!info.count){setPreviewUrl(old=>{if(old)URL.revokeObjectURL(old);return null;});setFolderName(\'\');setStatus(\'No supported images in folder\');return;}const target=Math.max(0,Math.min(index,info.count-1));const preview=await VisionAppAPI.utilityFolderPreview(programId,workspaceAlias,sourceDir.trim(),target);setFolderIndex(preview.index);showBlob(preview.blob,preview.name);setStatus(`${preview.index+1} / ${preview.count}`);}catch(e:any){onError(e?.response?.data?.detail||e?.message||\'Folder preview failed\');}finally{setBusy(false);}};\n const capture=async()=>{try{validate();if(!camera)throw new Error(\'Assign an enabled camera to this Workspace first.\');setBusy(true);setStatus(\'Capturing and saving...\');await onPersistWorkspace(nextWorkspace());const result=await VisionAppAPI.utilityGatherCapture(programId,workspaceAlias,plan());setLastResult(result);const blob=await VisionAppAPI.automationLatestFrame(programId,workspaceAlias);showBlob(blob,result.stem+\'.jpg\');setStatus(`Saved ${result.saved_count} output(s)${result.failed_count?` · ${result.failed_count} failed`:\'\'}`);}catch(e:any){onError(e?.response?.data?.detail||e?.message||\'Utility capture failed\');setStatus(\'Capture failed\');}finally{setBusy(false);}};\n const captureBurst=async()=>{try{validate();if(!camera)throw new Error(\'Assign an enabled camera to this Workspace first.\');setBusy(true);setStatus(`Capturing burst ×${manualBurst}...`);await onPersistWorkspace(nextWorkspace());const result=await VisionAppAPI.utilityGatherBurst(programId,workspaceAlias,{...plan(),samples:Math.max(1,manualBurst),interval_ms:Math.max(0,manualInterval)});setLastResult(result);const blob=await VisionAppAPI.automationLatestFrame(programId,workspaceAlias);showBlob(blob,`burst-${result.samples_processed}.jpg`);setStatus(`Burst ${result.samples_processed}/${result.samples_requested} · saved ${result.saved_count}`);}catch(e:any){onError(e?.response?.data?.detail||e?.message||\'Utility burst failed\');setStatus(\'Burst failed\');}finally{setBusy(false);}};\n const runBatch=async()=>{try{validate();if(!sourceDir.trim())throw new Error(\'Set an image source folder.\');setBusy(true);setStatus(\'Running folder batch...\');const result=await VisionAppAPI.utilityGatherBatch(programId,workspaceAlias,{...plan(),source_dir:sourceDir.trim()});setLastResult(result);setStatus(`Processed ${result.processed_count}/${result.source_count} image(s) · saved ${result.saved_count}`);}catch(e:any){onError(e?.response?.data?.detail||e?.message||\'Utility folder batch failed\');setStatus(\'Batch failed\');}finally{setBusy(false);}};\n const addManual=(rect:NormalizedRect)=>{const roi=manualRoi(rect,manual.length);setManual(items=>[...items,roi]);setSelectedId(roi.roi_id);setDrawMode(false);};\n const removeManual=(id:string)=>{setManual(items=>items.filter(item=>item.roi_id!==id));if(selectedId===id)setSelectedId(null);};\n const updateManualName=(id:string,name:string)=>setManual(items=>items.map(item=>item.roi_id===id?{...item,name,alias:safeFolder(name).toUpperCase()}:item));\n const applyPaint=(id:string)=>{if(!paintDestination)return false;setRoutes(current=>({...current,[id]:{enabled:true,destination:paintDestination}}));return true;};\n const selectRoi=(id:string|null)=>{if(id&&applyPaint(id))return;setSelectedId(id);};\n const routeClick=(id:string)=>{if(applyPaint(id))return;if(id!==FULL)setSelectedId(id);};\n return <div className="flex h-full min-h-0 bg-[#202124]">\n  <section className="relative min-w-0 flex-1"><VisionViewport imageUrl={previewUrl} rois={allRois} selectedId={selectedId} drawMode={drawMode} onSelect={selectRoi} onDraw={addManual}/><div className="absolute left-3 top-3 z-20 rounded border border-[#3c4043] bg-[#202124]/95 px-2 py-1 text-[8px] text-[#9aa0a6]">{mode===\'camera\'?(camera?`Camera: ${camera.alias}`:\'No camera assigned\'):(folderName||\'Folder source\')}</div>{paintDestination?<div className="absolute right-3 top-3 z-20 flex items-center gap-2 rounded border border-[#fdd663] bg-[#3a3524]/95 px-2 py-1 text-[8px] text-[#fdd663]"><Pipette size={10}/>Route brush: <b className="font-mono">{paintDestination}</b><button onClick={()=>setPaintDestination(null)}><X size={10}/></button></div>:null}</section>\n  <aside className="w-[520px] shrink-0 overflow-y-auto border-l border-[#3c4043] bg-[#292a2d] p-3 text-[8px]">\n   <div className="mb-3"><div className="text-[10px] font-black text-[#c58af9]">UTILITIES · DATA GATHERING v0.15.1</div><div className="mt-1 leading-4 text-[#9aa0a6]">Gather once, burst over time, or attach gathering to the production Workspace cycle. Working and Utilities share the same primary frame in BOTH mode.</div></div>\n   <div className="mb-3 rounded-lg border border-[#5f6368] bg-[#242528] p-2"><div className="mb-2 flex items-center"><b className="flex-1 text-[#fdd663]">UTILITIES ACTIVE</b><button disabled={busy} onClick={()=>void saveConfig()} className="cv-btn"><Save size={10}/>Save config</button></div><div className="grid grid-cols-3 gap-1">{([\'off\',\'utilities_only\',\'both\'] as ActiveMode[]).map(value=><button key={value} onClick={()=>setActiveMode(value)} className={`cv-btn justify-center ${activeMode===value?\'border-[#81c995] bg-[#1f6b38] text-white\':\'\'}`}>{value===\'off\'?\'OFF\':value===\'utilities_only\'?\'UTILITIES ONLY\':\'BOTH\'}</button>)}</div><div className="mt-2 grid grid-cols-2 gap-2"><label>Samples / cycle<input type="number" min={1} max={100} value={samplesPerCycle} onChange={e=>setSamplesPerCycle(Math.max(1,Number(e.target.value)||1))} className="cv-field w-full"/></label><label>Interval ms<input type="number" min={0} max={60000} value={intervalMs} onChange={e=>setIntervalMs(Math.max(0,Number(e.target.value)||0))} className="cv-field w-full"/></label></div><div className="mt-1 text-[#80868b]">Automation/Soft Trigger production cycles honor this mode after the Program is saved. Working Test/Run Bound Input stays inspection-only.</div></div>\n   <div className="mb-3 grid grid-cols-2 gap-2"><button onClick={()=>setMode(\'camera\')} className={`cv-btn justify-center ${mode===\'camera\'?\'border-[#8ab4f8] bg-[#174ea6]\':\'\'}`}><Camera size={11}/>Camera Collection</button><button onClick={()=>setMode(\'folder\')} className={`cv-btn justify-center ${mode===\'folder\'?\'border-[#8ab4f8] bg-[#174ea6]\':\'\'}`}><FolderOpen size={11}/>Offline Folder</button></div>\n   {mode===\'folder\'?<div className="mb-3 rounded-lg border border-[#3c4043] bg-[#242528] p-2"><div className="mb-1 font-black">SOURCE FOLDER</div><div className="flex gap-1"><input value={sourceDir} onChange={e=>setSourceDir(e.target.value)} placeholder="/path/to/raw_images" className="cv-field !mt-0 flex-1 font-mono"/><button disabled={busy||!sourceDir.trim()} onClick={()=>void loadFolder(0)} className="cv-icon"><RefreshCw size={11}/></button></div><div className="mt-2 flex items-center gap-1"><button disabled={busy||folderIndex<=0} onClick={()=>void loadFolder(folderIndex-1)} className="cv-icon"><ChevronLeft size={11}/></button><button disabled={busy||!folderCount||folderIndex>=folderCount-1} onClick={()=>void loadFolder(folderIndex+1)} className="cv-icon"><ChevronRight size={11}/></button><span className="font-mono text-[#9aa0a6]">{folderCount?`${folderIndex+1}/${folderCount}`:\'0 images\'}</span><span className="ml-auto truncate font-mono text-[#65d1ff]">{folderName}</span></div></div>:<div className="mb-3 rounded-lg border border-[#3c4043] bg-[#242528] p-2"><div className="font-black">WORKSPACE CAMERA</div><div className="mt-1 font-mono text-[#65d1ff]">{camera?`${camera.alias} · ${camera.driver}`:\'No camera assigned\'}</div><div className="mt-2 grid grid-cols-[1fr_80px_80px] gap-1"><button disabled={busy||!camera} onClick={()=>void capture()} className="cv-btn justify-center border-[#81c995] bg-[#1f6b38] text-white"><Camera size={10}/>Capture Once</button><input type="number" min={1} max={100} value={manualBurst} onChange={e=>setManualBurst(Math.max(1,Number(e.target.value)||1))} className="cv-field !mt-0" title="Burst samples"/><input type="number" min={0} max={60000} value={manualInterval} onChange={e=>setManualInterval(Math.max(0,Number(e.target.value)||0))} className="cv-field !mt-0" title="Interval ms"/></div><button disabled={busy||!camera} onClick={()=>void captureBurst()} className="cv-btn mt-1 w-full justify-center border-[#8ab4f8] text-[#8ab4f8]"><Layers3 size={10}/>Capture Burst ×{manualBurst} · {manualInterval} ms</button></div>}\n   <div className="mb-3 rounded-lg border border-[#3c4043] bg-[#242528] p-2"><div className="flex items-center gap-2"><b className="flex-1">EXTRACTION ROI</b><label className="flex items-center gap-1"><input type="checkbox" checked={useMaster} onChange={e=>setUseMaster(e.target.checked)}/>Master ROIs ({workspace.master.rois.length})</label><button disabled={!previewUrl} onClick={()=>setDrawMode(v=>!v)} className={`cv-btn ${drawMode?\'border-[#81c995] text-[#81c995]\':\'\'}`}><Plus size={10}/>Draw ROI</button></div>{manual.length?<div className="mt-2 space-y-1">{manual.map(roi=><div key={roi.roi_id} className="flex items-center gap-1"><input className="cv-field !mt-0 flex-1" value={roi.name} onChange={e=>updateManualName(roi.roi_id,e.target.value)} onFocus={()=>setSelectedId(roi.roi_id)}/><button onClick={()=>removeManual(roi.roi_id)} className="cv-icon text-[#f28b82]"><Trash2 size={10}/></button></div>)}</div>:null}</div>\n   <div className="mb-3 rounded-lg border border-[#3c4043] bg-[#242528] p-2"><div className="mb-1 flex items-center gap-2"><Sparkles size={10} className="text-[#c58af9]"/><b className="flex-1">ROI SAMPLING AUGMENTATION</b><label><input type="checkbox" checked={augmentation.enabled} onChange={e=>setAugmentation(a=>({...a,enabled:e.target.checked}))}/> enable</label></div><div className="grid grid-cols-4 gap-1"><label>Extra variants<input type="number" min={0} max={64} value={augmentation.extra_variants} onChange={e=>setAugmentation(a=>({...a,extra_variants:Math.max(0,Number(e.target.value)||0)}))} className="cv-field w-full"/></label><label>Shift X %<input type="number" step="1" min={0} max={50} value={Math.round(augmentation.shift_x_pct*100)} onChange={e=>setAugmentation(a=>({...a,shift_x_pct:Math.max(0,Number(e.target.value)||0)/100}))} className="cv-field w-full"/></label><label>Shift Y %<input type="number" step="1" min={0} max={50} value={Math.round(augmentation.shift_y_pct*100)} onChange={e=>setAugmentation(a=>({...a,shift_y_pct:Math.max(0,Number(e.target.value)||0)/100}))} className="cv-field w-full"/></label><label>Min IoU<input type="number" step=".05" min={0} max={1} value={augmentation.min_iou} onChange={e=>setAugmentation(a=>({...a,min_iou:Math.max(0,Math.min(1,Number(e.target.value)||0))}))} className="cv-field w-full"/></label><label>Scale min<input type="number" step=".01" min={.5} max={2} value={augmentation.min_scale} onChange={e=>setAugmentation(a=>({...a,min_scale:Number(e.target.value)||1}))} className="cv-field w-full"/></label><label>Scale max<input type="number" step=".01" min={.5} max={2} value={augmentation.max_scale} onChange={e=>setAugmentation(a=>({...a,max_scale:Number(e.target.value)||1}))} className="cv-field w-full"/></label><label className="col-span-2 flex items-end gap-1 pb-1"><input type="checkbox" checked={augmentation.include_original} onChange={e=>setAugmentation(a=>({...a,include_original:e.target.checked}))}/> Include original ROI</label></div><div className="mt-1 text-[#80868b]">Geometry only: pixels are untouched. Generated ROIs are clamped and rejected below Min IoU.</div></div>\n   <div className="mb-2 rounded-lg border border-[#3c4043] bg-[#242528] p-2"><div className="mb-1 flex items-center gap-2"><b className="flex-1">OUTPUT ROUTING</b>{paintDestination?<button onClick={()=>setPaintDestination(null)} className="cv-btn border-[#fdd663] text-[#fdd663]"><X size={9}/>Stop brush</button>:<span className="text-[#80868b]">Pick a route, then click rows/ROI boxes</span>}</div><input value={baseDir} onChange={e=>setBaseDir(e.target.value)} placeholder="Base output folder, e.g. /data/vision_collection" className="cv-field !mt-0 w-full font-mono"/></div>\n   <div className="space-y-1">{outputRows.map(row=>{const route=routes[row.id]??{enabled:true,destination:\'\'};return <div key={row.id} className={`rounded border p-2 ${selectedId===row.id?\'border-[#fdd663] bg-[#3a3524]\':\'border-[#3c4043] bg-[#242528]\'}`} onClick={()=>routeClick(row.id)}><div className="flex items-center gap-2"><input type="checkbox" checked={route.enabled} onClick={e=>e.stopPropagation()} onChange={e=>setRoutes(s=>({...s,[row.id]:{...route,enabled:e.target.checked}}))}/><ImageIcon size={10} className={row.kind===\'frame\'?\'text-[#8ab4f8]\':row.kind===\'master\'?\'text-[#81c995]\':\'text-[#fdd663]\'}/><b className="w-[115px] truncate">{row.name}</b><input value={route.destination} onChange={e=>setRoutes(s=>({...s,[row.id]:{...route,destination:e.target.value}}))} onClick={e=>e.stopPropagation()} className="cv-field !mt-0 flex-1 font-mono" placeholder="destination folder"/><button disabled={!route.destination.trim()} onClick={e=>{e.stopPropagation();setPaintDestination(route.destination.trim());}} className={`cv-icon ${paintDestination===route.destination.trim()&&route.destination.trim()?\'border-[#fdd663] text-[#fdd663]\':\'\'}`} title="Use this destination as route brush"><Pipette size={10}/></button></div></div>;})}</div>\n   <div className="mt-3 flex items-center gap-2 border-t border-[#3c4043] pt-3">{mode===\'folder\'?<button disabled={busy||!sourceDir.trim()} onClick={()=>void runBatch()} className="cv-btn border-[#81c995] bg-[#1f6b38] text-white"><FolderOpen size={11}/>{busy?<Loader2 size={11} className="animate-spin"/>:\'Run Folder Batch\'}</button>:null}<span className="flex-1 truncate text-[#9aa0a6]">{status}</span></div>\n   {lastResult?<div className="mt-2 rounded border border-[#3c4043] bg-[#202124] p-2 font-mono text-[7px] text-[#9aa0a6]">{\'processed_count\' in lastResult?<>source={lastResult.source_count} processed={lastResult.processed_count} saved={lastResult.saved_count} failed={lastResult.failed_count}</>:\'samples_processed\' in lastResult?<>samples={lastResult.samples_processed}/{lastResult.samples_requested} saved={lastResult.saved_count} failed={lastResult.failed_count}</>:<>stem={lastResult.stem} saved={lastResult.saved_count} failed={lastResult.failed_count}</>}</div>:null}\n  </aside>\n </div>;\n};\n'
REGRESSION_TEST = "from types import SimpleNamespace\n\nimport numpy as np\n\nfrom app.services.vision_app.automation_manager import AutomationManager\nfrom app.services.vision_app.models import (\n    NormalizedRect,\n    UtilitiesConfig,\n    UtilityActiveGatherConfig,\n    UtilityGatherAugmentation,\n    UtilityGatherPlan,\n    UtilityGatherRoi,\n    UtilityGatherRoute,\n    VisionProgramDefinition,\n    WorkspaceDefinition,\n)\nfrom app.services.vision_app.utilities_runtime import UtilityGatherRuntime\n\n\ndef _image():\n    yy, xx = np.mgrid[:120, :160]\n    return np.dstack([(xx % 255).astype(np.uint8), (yy % 255).astype(np.uint8), ((xx + yy) % 255).astype(np.uint8)])\n\n\ndef _plan(root, *, augmentation=True):\n    return UtilityGatherPlan(\n        base_dir=str(root),\n        routes=[\n            UtilityGatherRoute(output_id='__full__', destination='full'),\n            UtilityGatherRoute(output_id='pem', destination='pem'),\n        ],\n        rois=[UtilityGatherRoi(roi_id='pem', name='PEM', rect=NormalizedRect(x=.25, y=.25, w=.35, h=.35))],\n        augmentation=UtilityGatherAugmentation(\n            enabled=augmentation,\n            include_original=True,\n            extra_variants=4 if augmentation else 0,\n            shift_x_pct=.05,\n            shift_y_pct=.05,\n            min_scale=1.0,\n            max_scale=1.10,\n            min_iou=.70,\n        ),\n    )\n\n\ndef test_roi_sampling_augmentation_is_deterministic_and_multiplies_samples(tmp_path):\n    runtime = UtilityGatherRuntime()\n    plan = _plan(tmp_path)\n    result = runtime.save_frame(_image(), plan, stem='part_001')\n    assert result['failed_count'] == 0\n    assert result['saved_count'] == 6  # full + original ROI + four deterministic variants\n    assert len(list((tmp_path / 'full').glob('*.jpg'))) == 1\n    assert len(list((tmp_path / 'pem').glob('*.jpg'))) == 5\n\n    roi = plan.rois[0]\n    first = runtime._variant_rects(roi, plan.augmentation, seed_stem='fixed')\n    second = runtime._variant_rects(roi, plan.augmentation, seed_stem='fixed')\n    assert first == second\n    assert first[0][0] == 'orig'\n    assert all(runtime._iou(runtime._rect_tuple(roi.rect), rect) >= .70 for _, rect in first)\n\n\ndef test_workspace_utilities_config_defaults_off():\n    ws = WorkspaceDefinition(workspace_id='workspace_1')\n    assert ws.utilities.gathering.mode == 'off'\n    assert ws.utilities.gathering.samples_per_cycle == 1\n    assert ws.utilities.gathering.plan.augmentation.include_original is True\n\n\nclass _Repo:\n    def __init__(self, program): self.program = program\n    def get(self, program_id):\n        assert program_id == self.program.program_id\n        return self.program\n\n\ndef _program(tmp_path, mode):\n    plan = UtilityGatherPlan(\n        base_dir=str(tmp_path),\n        routes=[UtilityGatherRoute(output_id='__full__', destination='frames')],\n        rois=[],\n    )\n    ws = WorkspaceDefinition(\n        workspace_id='workspace_1',\n        alias='front',\n        utilities=UtilitiesConfig(gathering=UtilityActiveGatherConfig(mode=mode, plan=plan, samples_per_cycle=1, interval_ms=0)),\n    )\n    return VisionProgramDefinition(program_id='program_1', name='Program', workspaces=[ws], active_workspace_id='workspace_1')\n\n\ndef test_both_mode_gathers_primary_frame_then_runs_working_on_same_frame(tmp_path):\n    program = _program(tmp_path, 'both')\n    manager = AutomationManager(repository=_Repo(program))\n    seen = {}\n    working = SimpleNamespace(overall_ok=True)\n\n    def fake_run(program_id, image=None, workspace_alias=None):\n        seen['image'] = np.ascontiguousarray(image.copy())\n        seen['workspace'] = workspace_alias\n        return working\n\n    manager.run_inspection = fake_run  # type: ignore[method-assign]\n    source = _image()\n    cycle = manager.run_workspace_cycle('program_1', image=source, workspace_alias='front')\n    assert cycle['mode'] == 'both'\n    assert cycle['working'] is working\n    assert cycle['utilities']['saved_count'] == 1\n    assert np.array_equal(seen['image'], source)\n    assert seen['workspace'] == 'front'\n\n\ndef test_utilities_only_never_calls_working(tmp_path):\n    program = _program(tmp_path, 'utilities_only')\n    manager = AutomationManager(repository=_Repo(program))\n\n    def should_not_run(*args, **kwargs):\n        raise AssertionError('Working must not execute in utilities_only mode')\n\n    manager.run_inspection = should_not_run  # type: ignore[method-assign]\n    cycle = manager.run_workspace_cycle('program_1', image=_image(), workspace_alias='front')\n    assert cycle['working'] is None\n    assert cycle['utilities']['samples_processed'] == 1\n    assert cycle['utilities']['saved_count'] == 1\n"
CONTEXT_NOTE = "# Computer Vision v0.15.1 — Utilities Active / Burst / ROI Sampling\n\n## Purpose\n\nExtend the v0.15.0 Data Gathering utility from an operator-only tool into a Workspace-owned harvesting capability that can participate in production cycles without becoming part of Working inspection logic.\n\n## Files touched / closely related\n\n- `BE:app/services/vision_app/models.py` — persistent Workspace Utilities config, burst and ROI-sampling contracts.\n- `BE:app/services/vision_app/utilities_runtime.py` — filesystem harvesting plus deterministic shift/scale ROI sampling augmentation.\n- `BE:app/services/vision_app/automation_manager.py` — production Workspace cycle router and same-frame Working/Utilities fan-out.\n- `BE:app/services/vision_app/endpoint_registry.py` — Utilities state plus cycle/working actions in Automation IDE.\n- `BE:app/api/v1/endpoints/vision_app_api.py` — burst and explicit Workspace-cycle routes.\n- `FE:src/api/visionAppApi.ts` — Utilities v0.15.1 contracts.\n- `FE:src/components/ComputerVision/UtilitiesWorkspace.tsx` — routing brush, Active modes, burst and ROI sampling controls.\n- `FE:src/Pages/ComputerVisionPage.tsx` — Workspace persistence wiring and v0.15.1 baseline.\n- `BE:tests/vision_app/test_vision_app_v1510.py` — regression contracts.\n\n## Architectural invariants\n\n1. Utilities remains a tooling/data-harvesting plane. It does not own Dataset, Training, AI model or inspection-decision semantics.\n2. Utilities configuration is Workspace-owned. No Workspace may inherit another Workspace's gather plan or destinations.\n3. `Working` remains inspection-only. Engineering `test-run` and the existing `/workspaces/<alias>/run` route continue to call Working directly.\n4. Production Automation actions (`system.run_inspection`, `workspace.<alias>.run_inspection`) and Soft Trigger dispatch use the production Workspace-cycle router. With Utilities Active OFF this is behavior-compatible with v0.15.0.\n5. `UTILITIES_ONLY` gathers data and intentionally skips Working. It does not fabricate OK/NG or `logic_ready` results.\n6. `BOTH` gathers the primary frame and then runs Working exactly once on that same primary frame. Extra burst frames are Utilities-only.\n7. Burst gathering finishes before Working emits `run_finish`; this prevents a downstream automation step from removing the product before all requested temporal samples are collected.\n8. Basler burst capture reuses `CameraResourceController.capture()`. If native streaming owns the device, capture snapshots the latest `Streaming_frame` rather than opening a second camera handle.\n9. ROI sampling augmentation changes crop geometry only. It does not mutate image pixels. Variants are deterministic, clamped to image bounds, and rejected below the configured minimum IoU with the original ROI.\n10. The legacy `VisionTriggerRunnerManager` remains a compatibility runtime and is not migrated into the Workspace Utilities cycle in this version.\n\n## Utilities Active modes\n\n- `off` — production cycle runs Working only.\n- `utilities_only` — production cycle gathers configured samples and skips Working.\n- `both` — production cycle gathers first, then Working inspects the exact primary gathered frame once.\n\n## New Automation actions / state\n\n- `system.run_inspection()` — production cycle honoring Utilities Active.\n- `system.run_working()` — explicit Working-only bypass.\n- `workspace.<alias>.run_inspection()` — production cycle honoring Utilities Active.\n- `workspace.<alias>.run_cycle()` — explicit cycle alias.\n- `workspace.<alias>.run_working()` — explicit Working-only bypass.\n- `workspace.<alias>.utilities.active_mode`\n- `workspace.<alias>.utilities.samples_per_cycle`\n\nEvents added:\n\n- `workspace.<alias>.utilities_gathered`\n- `workspace.<alias>.cycle_finish`\n- `workspace.<alias>.cycle_error`\n\n## UI behavior\n\n- Route brush/pipette: choose one destination from any output row, then click other output rows or ROI boxes to apply that destination quickly. Escape or Stop Brush exits paint mode.\n- Manual burst: configure temporal sample count and interval; each frame is gathered independently.\n- Utilities Active config persists with the Workspace and can run while the Utilities UI is not open.\n- ROI Sampling Augmentation supports original inclusion, deterministic extra variants, X/Y shift bounds, context scale range and minimum IoU.\n\n## Recommended context for future changes\n\nMinimal:\n\n- `FE:src/Pages/ComputerVisionPage.tsx`\n- `FE:src/components/ComputerVision/UtilitiesWorkspace.tsx`\n- `FE:src/api/visionAppApi.ts`\n- `BE:app/services/vision_app/models.py`\n- `BE:app/services/vision_app/utilities_runtime.py`\n- `BE:app/services/vision_app/automation_manager.py`\n- `BE:app/services/vision_app/endpoint_registry.py`\n- `BE:app/api/v1/endpoints/vision_app_api.py`\n- `BE:tests/vision_app/test_vision_app_v1510.py`\n\nAdd `camera_resource_runtime.py` and `streaming_runtime.py` when changing burst acquisition or Soft Trigger/stream ownership.\n"
